def md_template(title, purpose, sections):
    rows = "\n".join(f"- [ ] **{item}** — Evidence / notes: `____________________________`" for item in sections)
    return f"""# {title}\n\n## Purpose\n{purpose}\n\n## Instructions\nComplete this document with the system owner and security reviewer. Link evidence instead of pasting credentials or sensitive production data. Mark unknown items explicitly; do not interpret an unchecked box as approval.\n\n## Review metadata\n| Field | Value |\n|---|---|\n| System / release | |\n| Business owner | |\n| Technical owner | |\n| Security reviewer | |\n| Review date | |\n| Next review date | |\n| Status | Draft / In review / Approved with conditions / Rejected |\n\n## Review items\n{rows}\n\n## Decisions and follow-up\n| ID | Decision or gap | Severity | Owner | Due date | Evidence | Status |\n|---|---|---|---|---|---|---|\n| EX-001 | Replace this safe example with a real reviewed item | Medium | Named role | YYYY-MM-DD | Evidence link or test ID | Open |\n\n## Reviewer guidance\nA completed template records evidence and accountable decisions; it does not certify that a system is secure or compliant. Re-open the review after material architecture, identity, data, dependency, or deployment changes.\n"""

