class GuideDoc(BaseDocTemplate):
    def __init__(self, filename, **kw):
        super().__init__(filename, **kw)
        self.addPageTemplates(PageTemplate(id="main", frames=Frame(self.leftMargin, self.bottomMargin, self.width, self.height, id="f"), onPage=self.art))
    def art(self, c, doc):
        c.saveState(); c.setFillColor(base.BG); c.rect(0, 0, A4[0], A4[1], fill=1, stroke=0)
        c.setStrokeColor(base.BORDER); c.line(20*mm, 15*mm, A4[0]-20*mm, 15*mm)
        c.setFillColor(base.MUTED); c.setFont("Helvetica", 8); c.drawString(20*mm, 9*mm, "DevVault  |  Security Review Templates"); c.drawRightString(A4[0]-20*mm, 9*mm, str(doc.page)); c.restoreState()
    def afterFlowable(self, f):
        if isinstance(f, Paragraph) and f.style.name in ("Chapter", "H2"):
            level = 0 if f.style.name == "Chapter" else 1; text = f.getPlainText(); key = f"h{level}-{self.seq.nextf('h')}"
            self.canv.bookmarkPage(key); self.canv.addOutlineEntry(text, key, level=level, closed=False); self.notify("TOCEntry", (level, text, self.page, key))

def build_pdf(path, sample=False):
    s = base.styles(); label = "PUBLIC SAMPLE" if sample else "COMPANION GUIDE"
    story = [Spacer(1, 27*mm), Paragraph("SECURITY REVIEW<br/>TEMPLATES", s["title"]), Paragraph("Evidence-led application reviews, actionable findings, and accountable release decisions", s["sub"]), Spacer(1, 10*mm), Table([[label], ["DevVault Security Review Pack"], ["Sixteen editable templates plus worked review guidance"], ["Edition 1.0  |  October 2026"]], colWidths=[160*mm], style=TableStyle([("BACKGROUND", (0,0), (-1,0), base.VIOLET), ("BACKGROUND", (0,1), (-1,-1), base.PLUM), ("TEXTCOLOR", (0,0), (-1,-1), base.IVORY), ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"), ("BOX", (0,0), (-1,-1), 1, base.BORDER), ("INNERGRID", (0,0), (-1,-1), .25, base.BORDER), ("LEFTPADDING", (0,0), (-1,-1), 8), ("TOPPADDING", (0,0), (-1,-1), 8), ("BOTTOMPADDING", (0,0), (-1,-1), 8)])), Spacer(1, 9*mm), Paragraph("These materials support structured reviews but do not guarantee that an application is secure or compliant. Never place credentials, customer data, or exploit secrets in review evidence.", s["small"]), PageBreak()]
    if sample:
        selected = GUIDE[:3]
        story += [Paragraph("Inside this limited sample", s["chapter"]), Paragraph("This sample introduces the review workflow and threat modeling, then shows an abbreviated intake template. The paid ZIP, full guide, complete checklists, registers, trackers, and sign-off materials are not included.", s["body"]), PageBreak()]
    else:
        selected = GUIDE
        story += [Paragraph("Contents", s["chapter"])]; toc = TableOfContents(); toc.levelStyles = [s["toc0"], s["toc1"]]; story += [toc, PageBreak()]
    for i, (title, explanation) in enumerate(selected, 1):
        operations, failures, exercise, code = CHAPTER_DETAIL[title]
        diagram = ["SCOPE", "MAP", "TEST", "PRIORITIZE", "REMEDIATE", "VERIFY"]
        story += base.chapter((title, explanation, operations, failures, exercise, diagram, code), i, s)
    if sample:
        story += [Paragraph("Abbreviated intake example", s["chapter"]), Paragraph("System: example private document API. Owner: application team. Data: confidential documents. Primary boundary: browser to authenticated API. Review status: In review. Open question: demonstrate cross-account denial with an integration test.", s["body"])]
    else:
        story += [Paragraph("Template selection map", s["chapter"]), Paragraph("Every review starts with intake, architecture/data flow, asset inventory, threat modeling, risk register, and findings tracker. Add identity and API reviews for authenticated services; database and privacy reviews for retained data; CI/CD and cloud reviews for deployment; incident readiness and sign-off before production release.", s["body"]), base.Flow(["INTAKE", "ARCHITECTURE", "CONTROL REVIEWS", "FINDINGS", "SIGN-OFF"]), PageBreak(), Paragraph("Final reviewer checklist", s["chapter"]), Paragraph("Scope and owners are explicit; evidence contains no secrets; data flows and trust boundaries are current; object authorization has negative tests; risks have owners and dates; accepted risks name accountable authority; fixes are independently verified; sign-off has conditions and expiry; material changes reopen the review.", s["body"])]
    doc = GuideDoc(str(path), pagesize=A4, leftMargin=20*mm, rightMargin=20*mm, topMargin=20*mm, bottomMargin=22*mm, title="Security Review Templates Companion Guide", author="DevVault", subject="Application security review templates and guidance")
    doc.multiBuild(story)

def validate_tree(folder):
    for path in folder.iterdir():
        text = path.read_text(encoding="utf-8")
        if re.search(r"(?i)(api[_-]?key|password|secret)\s*[=:]\s*[^\s`]*(live|prod|sk_|AKIA)", text):
            raise ValueError(f"Potential secret in {path.name}")
        if path.suffix == ".csv":
            with path.open(newline="", encoding="utf-8") as handle:
                rows = list(csv.reader(handle))
            if len(rows) < 2 or any(len(row) != len(rows[0]) for row in rows):
                raise ValueError(f"Invalid CSV {path.name}")

def main():
    parser = argparse.ArgumentParser(); parser.add_argument("--output-dir", required=True, type=Path); args = parser.parse_args()
    args.output_dir.mkdir(parents=True, exist_ok=True); editable = args.output_dir / "editable-templates"; editable.mkdir(exist_ok=True)
    for filename, title, purpose, sections in TEMPLATES:
        if filename in CSV_FILES:
            header, example = CSV_FILES[filename]
            with (editable / filename).open("w", newline="", encoding="utf-8") as handle: csv.writer(handle).writerows([header, example])
        else: (editable / filename).write_text(md_template(title, purpose, sections), encoding="utf-8")
    manifest = {"product": "Security Review Templates", "version": "1.0.0", "templateCount": len(TEMPLATES), "files": [name for name, *_ in TEMPLATES], "notice": "Review aids only; no security or compliance guarantee."}
    (editable / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    validate_tree(editable)
    zip_path = args.output_dir / "security-review-templates-editable-pack-v1.zip"
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(editable.iterdir()): archive.write(path, f"security-review-templates/{path.name}")
    build_pdf(args.output_dir / "security-review-templates-companion-guide-v1.pdf")
    build_pdf(args.output_dir / "security-review-templates-public-sample-v1.pdf", sample=True)
    print(json.dumps({"templates": len(TEMPLATES), "zip": str(zip_path)}, indent=2))

if __name__ == "__main__":
    main()
